(2962230, 416973, 45790, '<td valign="top">Not being familiar with NYC, the sign "Pennsylvania Station" stands out, leading me to believe that this is taken at the train station rather than Maddison Square Garden. But as I said, what do I know?</td>', 'Not being familiar with NYC, the sign "Pennsylvania Station" stands out, leading me to believe that this is taken at the train station rather than Maddison Square Garden. But as I said, what do I know?', '2006-10-25 16:58:24.000000', NULL, 1),
(2962235, 415029, 45790, '<td valign="top">I find the lighting especially attractive.</td>', 'I find the lighting especially attractive.', '2006-10-25 16:59:18.000000', NULL, 1),
(2962250, 416847, 45790, '<td valign="top">Busy, too much distortion (shooting upwards with wide angle lens), and nothing that particularly says "after".</td>', 'Busy, too much distortion (shooting upwards with wide angle lens), and nothing that particularly says "after".', '2006-10-25 17:01:49.000000', NULL, 1),
(2962254, 416756, 25331, '<td valign="top">I suggest for improvement to add a bit of saturation</td>', 'I suggest for improvement to add a bit of saturation', '2006-10-25 17:02:48.000000', NULL, 1),
(2962315, 417008, 65498, '<td valign="top">wonderful composition</td>', 'wonderful composition', '2006-10-25 17:22:15.000000', NULL, 1),
